package au.aumanet.app;
import android.Manifest;import android.content.*;import android.net.Uri;import android.os.*;import androidx.core.content.FileProvider;import androidx.lifecycle.Lifecycle;import com.getcapacitor.*;import com.getcapacitor.annotation.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Read-only snapshots; only explicit foreground actions arm/run/export. */
@CapacitorPlugin(name="AuMaNETLinkBenchmark",permissions={@Permission(alias="linkTestNotifications",strings={Manifest.permission.POST_NOTIFICATIONS})})
public final class LinkBenchmarkPlugin extends Plugin {
    private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean destroyed;private final java.util.concurrent.atomic.AtomicReference<Pending> pending=new java.util.concurrent.atomic.AtomicReference<>();
    private static final class Pending{final PluginCall call;final LinkBenchmarkController.Preparation preparation;Pending(PluginCall call,LinkBenchmarkController.Preparation preparation){this.call=call;this.preparation=preparation;}}
    private boolean foreground(){return !destroyed&&getActivity()!=null&&getActivity().getLifecycle().getCurrentState().isAtLeast(Lifecycle.State.RESUMED);}
    private LinkBenchmarkController controller()throws Exception{return LinkBenchmarkController.get(getContext());}
    private LinkBenchmarkController.Reply reply(PluginCall call){return new LinkBenchmarkController.Reply(){public void done(JSObject state){call.resolve(state);}public void failed(String code){call.reject("The link test could not continue. Check that both phones are armed and connected, and stop shared internet first.",code);}};}
    @PluginMethod public void snapshot(PluginCall call){try{controller().dispatch(()->controller().snapshot(),reply(call));}catch(Exception failed){call.reject("Link tests are unavailable","LINK_TEST_UNAVAILABLE");}}
    @PluginMethod public void arm(PluginCall call){
        if(!foreground()){call.reject("Open AuMaNET before arming a test","LINK_TEST_FOREGROUND_REQUIRED");return;}
        try{if(!"arm-link-test-for-15-minutes".equals(call.getData().optString("acknowledgement")))throw new IllegalArgumentException();Pending request=new Pending(call,controller().prepareArm());Pending old=pending.getAndSet(request);if(old!=null)controller().cancelPreparation(old.preparation);if(Build.VERSION.SDK_INT>=33&&getPermissionState("linkTestNotifications")!=PermissionState.GRANTED){requestPermissionForAlias("linkTestNotifications",call,"notifications");return;}armReady(request);}catch(Exception failed){call.reject("Link tests are unavailable","LINK_TEST_UNAVAILABLE");}
    }
    @PermissionCallback private void notifications(PluginCall call){Pending request=pending.get();if(request!=null&&request.call==call)armReady(request);}
    private void armReady(Pending request){
        if(pending.get()!=request)return;
        if(!foreground()||Build.VERSION.SDK_INT>=33&&getPermissionState("linkTestNotifications")!=PermissionState.GRANTED){pending.compareAndSet(request,null);try{controller().cancelPreparation(request.preparation);}catch(Exception ignored){}request.call.reject("Link tests need a visible Stop notification","LINK_TEST_NOTIFICATION_REQUIRED");return;}
        try{controller().dispatch(()->{if(!foreground()||pending.get()!=request)throw new IllegalStateException();JSObject state=controller().arm(request.call.getData(),request.preparation);pending.compareAndSet(request,null);return state;},new LinkBenchmarkController.Reply(){public void done(JSObject state){pending.compareAndSet(request,null);request.call.resolve(state);}public void failed(String code){pending.compareAndSet(request,null);request.call.reject("The selected group or link-test request changed",code);}});}catch(Exception failed){pending.compareAndSet(request,null);request.call.reject("Link tests are unavailable","LINK_TEST_UNAVAILABLE");}
    }
    @PluginMethod public void start(PluginCall call){if(!foreground()){call.reject("Open AuMaNET before starting a test","LINK_TEST_FOREGROUND_REQUIRED");return;}try{controller().dispatch(()->{if(!foreground())throw new IllegalStateException();return controller().start(call.getData());},reply(call));}catch(Exception failed){call.reject("Link tests are unavailable","LINK_TEST_UNAVAILABLE");}}
    @PluginMethod public void stop(PluginCall call){try{controller().stop(GroupNameMetadata.string(call.getData(),"expectedProcessId"),GroupNameMetadata.string(call.getData(),"expectedArmId"));snapshot(call);}catch(Exception failed){call.reject("Link tests are unavailable","LINK_TEST_UNAVAILABLE");}}
    @PluginMethod public void exportResults(PluginCall call){if(!foreground()){call.reject("Open AuMaNET before exporting results","LINK_TEST_FOREGROUND_REQUIRED");return;}try{String format=GroupNameMetadata.string(call.getData(),"format");if(!format.equals("json")&&!format.equals("csv"))throw new IllegalArgumentException();LinkBenchmarkController owner=controller();owner.dispatch(()->{String text=owner.export(format);File file=LinkBenchmarkExportFiles.create(new File(getContext().getCacheDir(),"link-benchmark-exports"),format,text,System.currentTimeMillis());Uri uri=FileProvider.getUriForFile(getContext(),getContext().getPackageName()+".fileprovider",file);main.post(()->{if(!foreground()){call.reject("Export was cancelled","LINK_TEST_CANCELLED");return;}try{Intent send=new Intent(Intent.ACTION_SEND).setType(format.equals("json")?"application/json":"text/csv").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newRawUri("AuMaNET link results",uri));getActivity().startActivity(Intent.createChooser(send,"Export field link results"));call.resolve(new JSObject().put("schema","aumanet.link-benchmark-export.v1").put("source","device").put("format",format).put("shared",true));}catch(Exception unavailable){call.reject("Results could not be shared","LINK_TEST_EXPORT_UNAVAILABLE");}});return new JSObject();},new LinkBenchmarkController.Reply(){public void done(JSObject ignored){}public void failed(String code){call.reject("Results could not be exported",code);}});}catch(Exception failed){call.reject("Results could not be exported","LINK_TEST_EXPORT_UNAVAILABLE");}}
    @Override protected void handleOnDestroy(){destroyed=true;Pending request=pending.getAndSet(null);if(request!=null)try{controller().cancelPreparation(request.preparation);}catch(Exception ignored){}super.handleOnDestroy();}
}
